BEGIN INSERT INTO archive_publication_abandonment_diagnostics(diagnostic_id,abandonment_id,kind,execution_generation,revision,phase,inventory_json,removed_json,build_sha256,recorded_at) VALUES(lower(hex(randomblob(16))),NEW.abandonment_id,'inventoried',NEW.execution_generation,NEW.revision,NEW.phase,NEW.inventory_json,NEW.removed_json,NEW.build_sha256,strftime('%Y-%m-%dT%H:%M:%fZ','now')); END;
