on,'$.month') IS ab.month)) AND ((json_extract(j.build_json,'$.timezone') IS ab.timezone AND json_extract(j.build_json,'$.root_reference_json') IS ab.root_reference_json) AND (json_extract(j.build_json,'$.header_json') IS ab.header_json AND json_extract(j.build_json,'$.header_sha256') IS ab.header_sha256)))) AND (((json_extract(j.build_json,'$.part_count') IS ab.part_count AND (json_extract(j.build_json,'$.record_count') IS ab.record_count AND json_extract(j.build_json,'$.state') IS ab.state)) AND ((json_extract(j.build_json,'$.revision') IS ab.revision AND json_extract(j.build_json,'$.lease_token') IS ab.lease_token) AND (json_extract(j.build_json,'$.lease_expires_at') IS ab.lease_expires_at AND json_extract(j.build_json,'$.next_part') IS ab.next_part))) AND ((json_extract(j.build_json,'$.next_offset') IS ab.next_offset AND (json_extract(j.build_json,'$.indexed_count') IS ab.indexed_count AND json_extract(j.build_json,'$.request_count') IS ab.request_count)) AND ((json_extract(j.build_json,'$.counts_json') IS ab.counts_json AND json_extract(j.build_json,'$.locator_digest') IS ab.locator_digest) AND (json_extract(j.build_json,'$.created_at') IS ab.created_at AND json_extract(j.build_json,'$.updated_at') IS ab.updated_at))))) AND (SELECT count(*) FROM json_each(j.build_json))=28 AND NOT EXISTS(SELECT 1 FROM json_each(j.build_json) pin WHERE pin.type!=CASE WHEN pin.key IN ('validator_version','part_count','record_count','revision','next_part','next_offset','indexed_count','request_count') THEN 'integer' WHEN pin.key IN ('lease_token','lease_expires_at') THEN 'null' ELSE 'text' END) AND json_remove(j.build_json,'$.publication_id','$.verification_id','$.generation','$.run_id','$.snapshot_commit_token','$.graph_sha256','$.validator_version','$.archive_id','$.center_id','$.month','$.timezone','$.root_reference_json','$.header_json','$.header_sha256','$.part_count','$.record_count','$.state','$.revision','$.lease_token','$.lease_expires_at','$.next_part','$.next_offset','$.indexed_count','$.request_count','$.counts_json','$.locator_digest','$.created_at','$.updated_at')='{}') AND NOT EXISTS(SELECT 1 FROM archive_publications WHERE publication_id=j.publication_id) AND NOT EXISTS(SELECT 1 FROM archive_publication_availability WHERE publication_id=j.publication_id) AND NOT EXISTS(SELECT 1 FROM archive_publication_reconciliation_jobs WHERE publication_id=j.publication_id) AND NOT EXISTS(SELECT 1 FROM archive_publication_reconciliation_receipts WHERE publication_id=j.publication_id) AND EXISTS(SELECT 1 FROM history_runtime WHERE id=1 AND state='ready' AND generation=j.execution_generation) AND NOT EXISTS(SELECT 1 FROM backup_runtime WHERE id=1 AND write_locked_until>strftime('%Y-%m-%dT%H:%M:%fZ','now')) AND EXISTS(SELECT 1 FROM json_each(j.selection_json) s WHERE OLD.request_id=json_extract(s.value,'$[0]')) AND EXISTS(SELECT 1 FROM history_request_keys k WHERE k.request_id=OLD.request_id AND k.source_kind=OLD.source_kind AND k.center_id=OLD.center_id AND k.payload_hash=OLD.payload_hash AND k.canonicalization='legacy-unverified') AND EXISTS(SELECT 1 FROM archive_publication_records r WHERE r.publication_id=OLD.publication_id AND r.table_name=OLD.table_name AND r.record_key=OLD.record_key))
